{
  "root_causes": [
    {
      "service": "ts-admin-user-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'normal' p, span_name, count(*) c, round(avg(duration)/1e6,1) avg_ms FROM normal_traces WHERE service_name='ts-admin-user-service' AND span_name='AdminUserController.getAllUsers' GROUP BY 1,2 UNION ALL SELECT 'abnormal', span_name, count(*), round(avg(duration)/1e6,1) FROM abnormal_traces WHERE service_name='ts-admin-user-service' AND span_name='AdminUserController.getAllUsers' GROUP BY 1,2",
          "claim": "AdminUserController.getAllUsers self-time rose from about 6.8 ms normal to about 1650 ms in the incident, with a tight 1647-1655 ms range."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) c, round(avg(duration)/1e6,1) avg_ms, round(min(duration)/1e6,1) min_ms FROM abnormal_traces WHERE service_name='ts-admin-user-service' AND span_name IN ('GET','GET /api/v1/adminuserservice/users') GROUP BY 1,2",
          "claim": "Outgoing GET client span stays around 7 ms while the enclosing server span takes about 1650 ms, so the extra time is inside the method, not on a callee or the wire."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, round(avg(value),3) avg_v, round(max(value),3) max_v FROM abnormal_metrics WHERE service_name='ts-admin-user-service' AND metric IN ('k8s.pod.cpu_limit_utilization','k8s.pod.memory_limit_utilization','container.cpu.usage') GROUP BY 1",
          "claim": "Pod CPU and memory utilisation stay low during the incident, so the slowdown is not resource saturation."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-admin-user-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) c, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE span_name='GET /api/v1/adminuserservice/users' GROUP BY 1,2,3",
          "claim": "The user-facing ts-ui-dashboard GET /api/v1/adminuserservice/users server span inherits the roughly 1650 ms delay from ts-admin-user-service."
        }
      ]
    }
  ]
}
